      && verifier.VerifyVectorOfData(tablePos, 74 /*GROUND_HEIGHTS_M*/, 4 /*float*/, false)
      && verifier.VerifyVectorOfData(tablePos, 76 /*PROFILE_HEIGHTS_M*/, 4 /*float*/, false)
      && verifier.VerifyVectorOfData(tablePos, 78 /*PROFILE_SURFACE_Z_M*/, 4 /*float*/, false)
      && verifier.VerifyString(tablePos, 80 /*TRACE_ID*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
